/** 연구 자료 꾸러미: the consented data of the open records, encrypted for the hospital research PC (SRS-DAT-014). */
import { useEffect, useState } from 'preact/hooks';
import { canGiveResearchData, researchConsentOf } from '../../data/consent';
import { db } from '../../data/db';
import { download } from '../../data/export';
import {
  STUDY_PASSWORD_MIN,
  buildPackage,
  checkStudyPassword,
  clearStudyPassword,
  hasStudyPassword,
  openPackage,
  packageFileName,
  sealPackage,
  setStudyPassword,
} from '../../data/researchPackage';
import { actions, getState, useApp } from '../../data/store';
import { activeSubject, normalizeCode } from '../../data/subjects';
import type { SessionSnapshots } from '../../data/types';
import { AppBar, Notice } from '../components/common';
import { Icon } from '../icons';
import { fmtDate } from '../labels';
import { showClinicalTools } from '../role';

type Msg = { tone: 'warn' | 'good' | 'danger'; text: string };

const pwInput = (value: string, set: (v: string) => void, label: string) => (
  <input
    class="grow"
    type="password"
    autoComplete="off"
    value={value}
    aria-label={label}
    placeholder={label}
    onInput={(e) => set((e.target as HTMLInputElement).value)}
  />
);

export function ResearchPackage() {
  const app = useApp();
  const consent = researchConsentOf(app.profile);
  const ok = canGiveResearchData(consent);
  const subject = activeSubject();
  // Own records (the patient's phone): the study code is typed at the visit and kept in the profile.
  const [typed, setTyped] = useState(app.profile?.studyCode ?? '');
  const code = subject ?? normalizeCode(typed);
  const [snaps, setSnaps] = useState<SessionSnapshots[]>([]);
  useEffect(() => {
    db.getAll<SessionSnapshots>('snapshots').then(setSnaps, () => setSnaps([]));
  }, []);
  const ids = new Set(app.sessions.map((s) => s.id));
  const photoCount = snaps.filter((s) => ids.has(s.id)).reduce((n, s) => n + Object.values(s.items).filter(Boolean).length, 0);
  const sealed = app.sessions.filter((s) => app.integrity[s.id]).length;
  const [registered, setRegistered] = useState(hasStudyPassword);
  const [pw, setPw] = useState('');
  const [pw2, setPw2] = useState('');
  const [setup, setSetup] = useState<{ a: string; b: string } | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const [msg, setMsg] = useState<Msg | null>(null);
  if (!app.profile) return null;

  const make = async () => {
    setMsg(null);
    if (!code) return setMsg({ tone: 'warn', text: '연구 코드를 적어 주세요(영문·숫자·하이픈 2~20자, 이름은 쓰지 마세요).' });
    if (pw.length < STUDY_PASSWORD_MIN) return setMsg({ tone: 'warn', text: `연구 비밀번호는 ${STUDY_PASSWORD_MIN}자 이상입니다.` });
    if (!registered && pw !== pw2) return setMsg({ tone: 'warn', text: '두 번 적은 비밀번호가 다릅니다.' });
    setBusy('비밀번호를 확인하고 암호화하는 중… (몇 초)');
    try {
      if (registered && !(await checkStudyPassword(pw))) {
        setMsg({ tone: 'warn', text: '이 기기에 등록한 연구 비밀번호와 다릅니다.' });
        return;
      }
      if (!subject && app.profile && app.profile.studyCode !== code) await actions.saveProfile({ ...app.profile, studyCode: code });
      const at = new Date();
      const pkg = await buildPackage(getState(), snaps, code, at);
      const file = await sealPackage(pkg, pw);
      // Self-check: the file opens with this password and holds what was meant to go in.
      const back = await openPackage(JSON.parse(JSON.stringify(file)), pw);
      if (back.content.sessions.length !== pkg.header.counts.sessions || back.content.photos.length !== pkg.header.counts.photos)
        throw new Error('SELF_CHECK');
      const name = packageFileName(code, at);
      download(name, JSON.stringify(file), 'application/json');
      setPw('');
      setPw2('');
      setMsg({
        tone: 'good',
        text: `${name} 파일을 만들었습니다(이 비밀번호로 열리는 것까지 확인). USB 케이블로 연구 PC에 옮긴 뒤 이 기기의 다운로드 폴더에서 지우세요. 메신저·이메일로 보내지 마세요.`,
      });
    } catch (e) {
      console.warn('research package failed', e);
      setMsg({ tone: 'danger', text: '파일을 만들지 못했습니다. 다시 시도해 주세요.' });
    } finally {
      setBusy(null);
    }
  };

  const register = async () => {
    if (!setup) return;
    if (setup.a.length < STUDY_PASSWORD_MIN) return setMsg({ tone: 'warn', text: `연구 비밀번호는 ${STUDY_PASSWORD_MIN}자 이상입니다.` });
    if (setup.a !== setup.b) return setMsg({ tone: 'warn', text: '두 번 적은 비밀번호가 다릅니다.' });
    setBusy('등록하는 중…');
    await setStudyPassword(setup.a);
    setBusy(null);
    setSetup(null);
    setRegistered(true);
    setMsg({ tone: 'good', text: '등록했습니다. 이제 파일을 만들 때 한 번만 적으면 되고, 틀리게 적으면 알려 줍니다.' });
  };

  return (
    <>
      <AppBar title="연구 자료 꾸러미" sub={subject ? `피험자 ${subject}` : '이 기기 주인의 기록'} onBack />
      <main class="main">
        <div class="card tight">
          <Notice>
            <span class="small">
              동의한 항목만 담아 연구용 비밀번호로 암호화한 파일을 만듭니다. 파일은 USB 케이블로 병원 연구 PC에 옮기고, 메신저·이메일로
              보내지 마세요. 이름·별명은 들어가지 않고 연구 코드만 들어갑니다.
            </span>
          </Notice>
        </div>

        {!ok ? (
          <div class="card warn">
            <Notice tone="warn">
              <span class="small">
                {consent?.withdrawn
                  ? `연구 참여를 철회해(${fmtDate(consent.at)}) 파일을 만들 수 없습니다.`
                  : '연구 참여 동의가 기록되지 않아 파일을 만들 수 없습니다. 설정 › 연구 참여에서 동의서에 적은 대로 항목을 기록하세요.'}
              </span>
            </Notice>
            <a class="btn block" href="#/settings">
              설정으로
            </a>
          </div>
        ) : (
          <>
            <div class="section-title">들어가는 것</div>
            <div class="card tight">
              <ul class="small" style={{ margin: 0, paddingLeft: '20px' }}>
                <li>
                  평가 {app.sessions.length}회 (봉인 확인 {sealed}/{app.sessions.length}) · 얼굴 점 좌표 포함
                </li>
                <li>
                  의료진 평가 {app.ratings.length}건 · 운동 기록 {app.rehab.length}건 · 연합운동 찾기 {app.synk.length}건 · 다시 찍은 기록{' '}
                  {app.rejections.length}건
                </li>
                <li>
                  {consent!.items.photos
                    ? `동작별 사진 ${photoCount}장${photoCount ? '' : ' (저장된 사진 없음)'}`
                    : '사진: 동의하지 않아 빠짐'}
                </li>
                <li>
                  2차 이용 {consent!.items.secondaryUse ? '동의' : '안 함'} · 인허가 자료 활용{' '}
                  {consent!.items.regulatory ? '동의' : '안 함'}
                  (파일에 함께 적힘)
                </li>
              </ul>
              <p class="xsmall muted" style={{ margin: '6px 0 0' }}>
                동의 {consent!.version} · {fmtDate(consent!.at)}. 마비 쪽·발병일·원인·출생 연도는 분석에 필요해 들어갑니다.
              </p>
            </div>

            <div class="section-title">연구 코드와 비밀번호</div>
            <div class="card">
              <div class="stack">
                {subject ? (
                  <div class="small">
                    연구 코드 <b>{subject}</b> <span class="xsmall muted">(이 피험자 기록의 코드)</span>
                  </div>
                ) : (
                  <input
                    class="grow"
                    type="text"
                    autoCapitalize="characters"
                    value={typed}
                    aria-label="연구 코드"
                    placeholder="연구 코드 (예: KHU-001)"
                    onInput={(e) => setTyped((e.target as HTMLInputElement).value)}
                  />
                )}
                {pwInput(pw, setPw, '연구 비밀번호')}
                {!registered && pwInput(pw2, setPw2, '한 번 더')}
              </div>
              <p class="xsmall muted" style={{ margin: '6px 0 8px' }}>
                연구진이 정한 비밀번호({STUDY_PASSWORD_MIN}자 이상)입니다. 이 기기에는 저장하지 않습니다. 비밀번호를 잊으면 연구 PC에서도 열
                수 없습니다.
              </p>
              <button class="btn primary block" disabled={!!busy} onClick={make}>
                <Icon name="download" /> 암호화해서 파일 만들기
              </button>
            </div>
          </>
        )}

        {busy && <p class="small center ink2">{busy}</p>}
        {msg && (
          <div class="card tight">
            <Notice tone={msg.tone}>
              <span class="small">{msg.text}</span>
            </Notice>
          </div>
        )}

        {showClinicalTools(app.profile) && (
          <>
            <div class="section-title">이 기기에 비밀번호 등록 (선택)</div>
            <div class="card">
              <p class="xsmall ink2" style={{ margin: '0 0 8px' }}>
                연구 기기라면 등록해 두세요. 비밀번호 대신 솔트를 넣은 해시만 남아, 파일을 만들 때 잘못 적으면 바로 알려 줍니다.
              </p>
              {registered && !setup ? (
                <div class="row">
                  <span class="chip good grow">
                    <Icon name="check" /> 등록됨
                  </span>
                  <button
                    class="btn sm ghost"
                    onClick={() => {
                      if (!confirm('등록한 연구 비밀번호 확인을 지웁니다. 이후에는 파일을 만들 때 두 번 적습니다.')) return;
                      clearStudyPassword();
                      setRegistered(false);
                    }}
                  >
                    지우기
                  </button>
                </div>
              ) : setup ? (
                <>
                  <div class="stack">
                    {pwInput(setup.a, (a) => setSetup({ ...setup, a }), '연구 비밀번호')}
                    {pwInput(setup.b, (b) => setSetup({ ...setup, b }), '한 번 더')}
                  </div>
                  <div class="row" style={{ marginTop: '8px' }}>
                    <button class="btn grow" onClick={() => setSetup(null)}>
                      취소
                    </button>
                    <button class="btn primary grow" disabled={!!busy} onClick={register}>
                      등록
                    </button>
                  </div>
                </>
              ) : (
                <button class="btn sm block" onClick={() => setSetup({ a: '', b: '' })}>
                  <Icon name="shield" /> 연구 비밀번호 등록
                </button>
              )}
            </div>
          </>
        )}
      </main>
    </>
  );
}
